import pytz
from pymongo import MongoClient
from datetime import datetime
from tzlocal import get_localzone_name

from taf.rfrl.procedures.resources.python.sw_update.SW_update import SW_update
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import get_mrbts_id_admin
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_result, log_operation
from taf.rfrl.procedures.resources.python.sw_stream.interface import get_sw_stream


class BenchmarkingDB:
    def __init__(self):
        self._mongo_session = None
        self._db_session = None
        self._collection = None
        self._bts_id = None
        self._sw_stream = None
        self._sw_version = None

    def setup(self, connection, bts_type="GNB"):
        """
        Prepare mandatory variables and connect to database
        :param connection: AdminConnection object or if used, string name alias.
        :type connection: AdminConnection or str
        :param bts_type: type of bts, can be 'GNB' or 'ENB'
        :type bts_type: str
        """
        log_operation("Collecting mandatory data from BTS...")
        self._bts_id = f"MRBTS-{get_mrbts_id_admin(connection=connection)}"
        self._sw_stream = get_sw_stream(device=bts_type)
        self._sw_version = SW_update().get_sw_version(bts_type=bts_type).raw

        log_operation("Connecting to MongoDB...")
        self._mongo_session = MongoClient(
            host="mongodb://ute_benchmarking:Ut3pa5s#1be1@10.42.194.82:5000/?authSource=PM_BENCHMARKING",
            connect=True
        )
        self._db_session = self._mongo_session["PM_BENCHMARKING"]
        self._collection = self._db_session[self._sw_stream]

        log_result("Connection to database successfully established!")

    def disconnect(self):
        """
        Close connection to MongoDB
        """
        self._mongo_session.close()

    @log_input_and_output
    def save_datetime_for_bts(self, tc_name, template_id, start_datetime, end_datetime, cycles):
        """
        Saves start and end datetime of desired KPIs and PMs counters collection time range
        user want to verify in the future. Timezone is automatically added to `start_datetime` and `end_datetime`
        args based on VM settings. To prevent discrepancies, make sure timezone on VM anb BTS are the same.

        :param tc_name: name of TC, e.g. 'General_SiSo_KPI_PM_Counters_benchmarking'
        :type tc_name: str
        :param template_id: id of template that user what to use in Scout Comparator report
        :type template_id: str
        :param start_datetime: start datetime of KPIs and PMs counters collection,
                               datetime provided as string must have specified format %Y-%m-%d %H:%M:%S
        :type start_datetime: datetime object or str
        :param end_datetime: end datetime of KPIs and PMs counters collection,
                             datetime provided as string must have specified format %Y-%m-%d %H:%M:%S
        :type end_datetime: datetime object or str
        :param cycles: number of full quarter cycles counted starting from the nearest quarter, e.g. there's 11:10, and
                       it's 5 minutes before quarter 11:15, so for 3 cycles starting counting at quarter 15 the ending
                       quarter will be 12:00
        :type cycles: Union[str, int]
        """
        local_timezone = get_localzone_name()
        start_datetime = self._unify_date_format(start_datetime, local_timezone)
        end_datetime = self._unify_date_format(end_datetime, local_timezone)

        log_operation(f"Saving data for '{self._bts_id}' in '{self._sw_stream}' collection")

        if not self._try_to_update_record(tc_name, template_id, start_datetime, end_datetime,
                                          cycles, local_timezone):
            self._insert_new_record(tc_name, template_id, start_datetime, end_datetime, cycles,
                                    local_timezone)

        log_result(f"Data successfully saved for '{self._bts_id}' in '{self._sw_stream}' collection!")

    @log_input_and_output
    def read_data_for_bts(self, tc_name, template_id, cycles, convert_to_saved_timezone=False):
        """
        Reads data for detected BTS and provided Scout template id. Start and end datetime are expressed in UTC timezone
        (GMT+0)
        :param tc_name: name of TC, e.g. 'General_SiSo_KPI_PM_Counters_benchmarking'
        :type tc_name: str
        :param template_id: id of template that user what to use in Scout Comparator report
        :type template_id: str
        :param cycles: number of full quarter cycles counted starting from the nearest quarter, e.g. there's 11:10, and
               it's 5 minutes before quarter 11:15, so for 3 cycles starting counting at quarter 15 the ending
               quarter will be 12:00
        :type cycles: Union[str, int]
        :param convert_to_saved_timezone: converts save timestamps from UTC to last saved timezone
                                          (MongoDB automatically converts saved datetime objects to UTC)
        :type convert_to_saved_timezone: bool
        :return: BTS data from database
        :rtype: dict
        """
        log_operation(f"Reading data for '{self._bts_id}' from '{self._sw_stream}' collection...")
        query_result = self._collection.find_one({"bts_name": self._bts_id, "tc_name": tc_name,
                                                  "template_id": str(template_id), "cycles": str(cycles)})

        query_result["start_datetime"] = query_result["start_datetime"].replace(tzinfo=pytz.utc)
        query_result["end_datetime"] = query_result["end_datetime"].replace(tzinfo=pytz.utc)
        if convert_to_saved_timezone:
            query_result["start_datetime"] = query_result["start_datetime"].astimezone(query_result["timezone"])
            query_result["end_datetime"] = query_result["end_datetime"].astimezone(query_result["timezone"])

        return query_result

    @log_input_and_output
    def check_if_record_exists_for_bts(self, tc_name, template_id, cycles):
        """
        Verifies if record for detected BTS and provided Scout template id exists
        :param tc_name: name of TC, e.g. 'General_SiSo_KPI_PM_Counters_benchmarking'
        :type tc_name: str
        :param template_id: id of template that user what to use in Scout Comparator report
        :type template_id: str
        :param cycles: number of full quarter cycles counted starting from the nearest quarter, e.g. there's 11:10, and
                       it's 5 minutes before quarter 11:15, so for 3 cycles starting counting at quarter 15 the ending
                       quarter will be 12:00
        :type cycles: Union[str, int]
        :return: True if record exists in database, False otherwise
        :rtype: bool
        """
        return bool(self._collection.find_one({"bts_name": self._bts_id, "tc_name": tc_name,
                                               "template_id": str(template_id), "cycles": str(cycles)}))

    @log_input_and_output
    def _try_to_update_record(self, tc_name, template_id, start_datetime, end_datetime, cycles, timezone):
        record_updated = bool(self._collection.find_one_and_update(
            {"bts_name": self._bts_id, "tc_name": tc_name, "template_id": str(template_id), "cycles": str(cycles)},
            {"$set": {"start_datetime": start_datetime, "end_datetime": end_datetime, "sw_version": self._sw_version,
                      "timezone": timezone, "updated_at": datetime.utcnow()}})
        )
        if record_updated:
            log_result(f"Record successfully updated for (bts_name: '{self._bts_id}', tc_name: '{tc_name}', "
                       f"cycles: '{cycles}').")
        else:
            log_result(f"No record found to update for (bts_name: '{self._bts_id}', "
                       f"tc_name: '{tc_name}', cycles: '{cycles}').")

        return record_updated

    @log_input_and_output
    def _insert_new_record(self, tc_name, template_id, start_datetime, end_datetime, cycles, timezone):
        log_operation("Creating new record...")
        self._collection.insert_one({"bts_name": self._bts_id, "tc_name": tc_name,
                                     "template_id": str(template_id), "start_datetime": start_datetime,
                                     "end_datetime": end_datetime, "cycles": str(cycles),
                                     "sw_version": self._sw_version, "timezone": timezone,
                                     "created_at": datetime.utcnow(), "updated_at": datetime.utcnow()})

        log_result(f"Successfully created new record for (bts_name: '{self._bts_id}', tc_name: '{tc_name}', "
                   f"cycles: '{cycles}').")

    @staticmethod
    @log_input_and_output
    def _unify_date_format(timestamp, timezone):
        if isinstance(timestamp, datetime):
            timestamp = timestamp.strftime("%Y-%m-%d %H:%M:%S")
        timestamp = datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S").replace(second=0)

        if not timestamp.tzinfo:
            local_timezone = pytz.timezone(timezone)
            timestamp = local_timezone.localize(timestamp, is_dst=None)

        return timestamp
